class User {
  + username : string
  + password : string
}

class Player extends User {
}

class Admin extends User {
  + createGame()
}

class Game {
  + name : string
  + minSpeed : float
  + speedIncreaseFactor : float
  + maxLength : float
  + minLength : float
  + isPublished : boolean
}

class Block {
  + color : string
  + points : int
}

class Level {
  + levelNumber : int
  + isRandom : boolean
  + startingArrangement : string[]
  + blocksAtStartCount : int
}

class HallOfFame {
}

class ScoreEntry {
  + score : int
}

class GameSession {
  + lives : int
  + currentScore : int
  + isPaused : boolean
}

Admin "1" -- "0..*" Game : manages
Game "1" -- "1" HallOfFame : has
HallOfFame "1" -- "0..*" ScoreEntry : contains
ScoreEntry "0..*" -- "1" Player : belongs to
Game "1" *-- "1..99" Level : consists of
Game "1" *-- "0..*" Block : defines
Level "1" -- "0..*" Block : uses
Player "0..*" -- "0..*" Game : plays
Player "0..1" -- "0..*" GameSession : participates in
GameSession "1" -- "1" Game : is a session of

@enduml

